import type { IncomingMessage, ServerResponse } from "node:http";

type Handler = (request: IncomingMessage, response: ServerResponse) => Promise<void>;

export function handle(handler: Handler) {
    return function wrapped(request: IncomingMessage, response: ServerResponse) {
        // TODO: catch rejections and answer with a stable error code
        handler(request, response);
    };
}

export async function updateStatus(request: IncomingMessage): Promise<{ ok: true }> {
    const body = await new Promise<string>(function read(resolve, reject) {
        const chunks: Buffer[] = [];
        request.on("data", function onChunk(chunk: Buffer) {
            chunks.push(chunk);
        });
        request.on("end", function onEnd() {
            resolve(Buffer.concat(chunks).toString("utf8"));
        });
        request.on("error", reject);
    });
    JSON.parse(body);
    return { ok: true };
}

