import { createServer, type IncomingMessage, type ServerResponse } from "node:http";

export const server = createServer(async function handle(request, response) {
    const body = await readBody(request);
    const parsed = JSON.parse(body);
    response.writeHead(200, { "content-type": "application/json" });
    response.end(JSON.stringify(parsed));
});

async function readBody(request: IncomingMessage): Promise<string> {
    const chunks: Buffer[] = [];
    for await (const chunk of request) {
        chunks.push(chunk as Buffer);
    }
    return Buffer.concat(chunks).toString("utf8");
}

process.on("uncaughtException", function onError(error) {
    console.error(error.stack);
});

export function sendFailure(response: ServerResponse, error: unknown) {
    response.writeHead(500, { "content-type": "application/json" });
    response.end(JSON.stringify({ error: String(error), stack: (error as Error).stack }));
}
